-- Phân bón Rynan nhập về 02/11/2026 (hóa đơn 9 dòng đầu; các dòng sau ảnh bị cắt, chưa nhập).
-- Giá lẻ theo GIÁ THỊ TRƯỜNG (chủ shop chọn, không dùng công thức của cây): giá các shop An Tín Nông, GreenHome; 19-19-09, 20-15-15 chưa thấy giá → theo 16-16-16;
-- Vetamate 140 bịch 500g chưa thấy giá → Claude ước 69.000đ. Giá vườn = đơn giá hóa đơn + 5% VAT, giá gốc = vườn + 10%. Không combo, không giá gạch.
-- Lãi thấp hơn giá sàn chung → bật "Không áp mã giảm giá". Ảnh = link ngoài của shop bán lẻ (product_images.file là link https, data rỗng).
-- Tồn = số lượng hóa đơn, chưa có số lô, hạn dùng 2029 (ghi 2029-01-01). Chạy lại không nhập trùng.
CREATE TEMP TABLE "_m81" ("ord" int, "slug" text PRIMARY KEY, "name" text, "spec" text, "lead" text, "specs" jsonb, "unit" text, "options" jsonb);--> statement-breakpoint
INSERT INTO "_m81" VALUES
(1, 'phan-tan-cham-rynan-flowermate-230', 'Phân tan chậm Rynan Flowermate 230 NPK 23-08-08+TE', 'Kiểng lá · Tan chậm 4 tháng', 'Phân bón tan chậm Rynan Flowermate 230, NPK 23-08-08 + vi lượng, đạm cao giúp cây ra lá xanh, mập. Hạt bọc màng polymer nhả dinh dưỡng đều khoảng 4 tháng, hợp kiểng lá, cây trong nhà, cây văn phòng.', '[["Thành phần", "N 23% · P₂O₅ 8% · K₂O 8% + vi lượng (TE)"], ["Liều dùng", "Rải quanh gốc 5–20g/chậu tùy cỡ cây, cách gốc 3–5cm, tưới nước sau khi bón"], ["Thời gian nhả dinh dưỡng", "Khoảng 120 ngày"], ["Phù hợp", "Kiểng lá, cây trong nhà, cây văn phòng"], ["Thương hiệu", "Rynan"], ["Hạn dùng", "36 tháng kể từ ngày sản xuất"]]'::jsonb, 'Bịch', '[{"label": "Bịch 90g", "garden": 28875, "cost": 31763, "price": 36000, "qty": 30, "img": "https://antinnong.com/wp-content/uploads/2026/07/phan-tan-cham-rynan-230-npk-23-8-8-90gr-an-tin-nong-hn.png"}, {"label": "Túi 500g", "garden": 61425, "cost": 67568, "price": 80000, "qty": 30, "img": "https://antinnong.com/wp-content/uploads/2026/07/phan-tan-cham-rynan-230-npk-23-8-8-500gr-an-tin-nong-hn.png"}]'::jsonb),
(2, 'phan-tan-cham-rynan-flowermate-240', 'Phân tan chậm Rynan Flowermate 240 NPK 14-14-14+TE', 'Hoa · Tan chậm 3 tháng', 'Phân bón tan chậm Rynan Flowermate 240, NPK 14-14-14 cân đối + vi lượng, nuôi cây đủ lá, rễ, hoa. Hạt bọc màng polymer nhả dinh dưỡng khoảng 3 tháng, hợp hoa hồng, cây hoa, cây cảnh chậu.', '[["Thành phần", "N 14% · P₂O₅ 14% · K₂O 14% + vi lượng (TE)"], ["Liều dùng", "5–10g/chậu nhỏ, 10–20g/cây lớn; rải quanh gốc rồi tưới nước"], ["Thời gian nhả dinh dưỡng", "Khoảng 90 ngày"], ["Phù hợp", "Hoa hồng, cây hoa, cây cảnh chậu"], ["Thương hiệu", "Rynan"], ["Hạn dùng", "36 tháng kể từ ngày sản xuất"]]'::jsonb, 'Bịch', '[{"label": "Bịch 90g", "garden": 28875, "cost": 31763, "price": 36000, "qty": 30, "img": "https://antinnong.com/wp-content/uploads/2025/06/phan-tan-cham-rynan-240-npk-14-14-14-90gr-an-tin-nong-hn.png"}, {"label": "Túi 500g", "garden": 61425, "cost": 67568, "price": 80000, "qty": 30, "img": "https://antinnong.com/wp-content/uploads/2026/07/phan-tan-cham-rynan-240-npk-14-14-14-500gr-an-tin-nong-hn.png"}]'::jsonb),
(3, 'phan-tan-cham-rynan-npk-16-16-16', 'Phân tan chậm Rynan NPK 16-16-16 hũ 150g', 'Cân đối · Hũ 150g', 'Phân tan chậm Rynan NPK 16-16-16, hạt bọc màng polymer, dinh dưỡng cân đối cho cây ăn trái trồng chậu, cây có múi, cây cảnh. Bón lại sau 60–90 ngày.', '[["Thành phần", "N 16% · P₂O₅ 16% · K₂O 16%"], ["Liều dùng", "10–20g/gốc cây 1–2 năm, 20–30g/gốc cây lớn đang cho trái"], ["Bón lại", "Sau 60–90 ngày"], ["Phù hợp", "Cây ăn trái, cây có múi, cây cảnh chậu"], ["Thương hiệu", "Rynan"], ["Hạn dùng", "36 tháng kể từ ngày sản xuất"]]'::jsonb, 'Hũ', '[{"label": "Hũ 150g", "garden": 15855, "cost": 17440, "price": 36000, "qty": 45, "img": "https://greenhome.com.vn/wp-content/uploads/2025/11/phan-tan-cham-rynan-npk-16-16-16-greenhome-150gr-11.png"}]'::jsonb),
(4, 'phan-bon-nam-viet-npk-18-8-22', 'Phân bón Nam Việt NPK 18-8-22 hũ 150g', 'Kali cao · Hũ 150g', 'Phân tan chậm Nam Việt (Rynan) NPK 18-8-22, kali cao giúp cây ra hoa, nuôi trái ngọt, cứng cây. Dùng cho cây ăn trái và cây cảnh trồng chậu.', '[["Thành phần", "N 18% · P₂O₅ 8% · K₂O 22%"], ["Liều dùng", "3–5g/chậu nhỏ; 5–10g/gốc cây 1–2 năm; 10–20g/gốc cây lớn"], ["Bón lại", "Sau 45–90 ngày"], ["Phù hợp", "Cây ăn trái, cây hoa, cây cảnh chậu"], ["Thương hiệu", "Nam Việt (Rynan)"], ["Hạn dùng", "36 tháng kể từ ngày sản xuất"]]'::jsonb, 'Hũ', '[{"label": "Hũ 150g", "garden": 15855, "cost": 17440, "price": 36000, "qty": 45, "img": "https://hoanghungagri.vn/wp-content/uploads/2026/02/2301-32.png"}]'::jsonb),
(5, 'phan-tan-cham-rynan-npk-19-19-09', 'Phân tan chậm Rynan NPK 19-19-09 hũ 150g', 'Lân cao · Hũ 150g', 'Phân tan chậm Rynan NPK 19-19-09, hạt bọc màng polymer, đạm và lân cao giúp cây ra rễ, đâm chồi, phát triển thân lá.', '[["Thành phần", "N 19% · P₂O₅ 19% · K₂O 9%"], ["Liều dùng", "Rải quanh gốc theo cỡ cây, khoảng 5–20g/chậu, tưới nước sau khi bón"], ["Phù hợp", "Cây con, cây đang ra rễ, đâm chồi"], ["Thương hiệu", "Rynan"], ["Hạn dùng", "36 tháng kể từ ngày sản xuất"]]'::jsonb, 'Hũ', '[{"label": "Hũ 150g", "garden": 15855, "cost": 17440, "price": 36000, "qty": 45, "img": "https://hoanghungagri.vn/wp-content/uploads/2026/02/2301-36.png"}]'::jsonb),
(6, 'phan-tan-cham-rynan-npk-20-15-15', 'Phân tan chậm Rynan NPK 20-15-15 hũ 150g', 'Đạm cao · Hũ 150g', 'Phân tan chậm Rynan NPK 20-15-15, hạt bọc màng polymer, đạm cao kèm lân, kali giúp cây xanh tốt, phát triển nhanh.', '[["Thành phần", "N 20% · P₂O₅ 15% · K₂O 15%"], ["Liều dùng", "Rải quanh gốc theo cỡ cây, khoảng 5–20g/chậu, tưới nước sau khi bón"], ["Phù hợp", "Cây cảnh, cây ăn trái giai đoạn phát triển thân lá"], ["Thương hiệu", "Rynan"], ["Hạn dùng", "36 tháng kể từ ngày sản xuất"]]'::jsonb, 'Hũ', '[{"label": "Hũ 150g", "garden": 15855, "cost": 17440, "price": 36000, "qty": 45, "img": "https://hoanghungagri.vn/wp-content/uploads/2026/02/2301-41.png"}]'::jsonb),
(7, 'phan-tan-cham-rynan-vetamate-140', 'Phân tan chậm Rynan Vetamate 140 NPK 27-08-08+TE (1% Humic)', 'Đạm cao · Humic', 'Phân tan chậm Rynan Vetamate 140, NPK 27-08-08 + vi lượng + 1% humic, đạm cao giúp rau, cây lá phát triển nhanh; humic giúp đất tơi, cây hút dinh dưỡng tốt hơn.', '[["Thành phần", "N 27% · P₂O₅ 8% · K₂O 8% + vi lượng (TE) + 1% Humic"], ["Liều dùng", "Rải quanh gốc theo cỡ cây, tưới nước sau khi bón"], ["Phù hợp", "Rau ăn lá, cây lá, cây cảnh"], ["Thương hiệu", "Rynan"], ["Hạn dùng", "36 tháng kể từ ngày sản xuất"]]'::jsonb, 'Bịch', '[{"label": "Bịch 500g", "garden": 50715, "cost": 55787, "price": 69000, "qty": 60, "img": null}]'::jsonb);--> statement-breakpoint
CREATE TEMP TABLE "_m81_new" ("slug" text PRIMARY KEY);--> statement-breakpoint
WITH base AS (
  SELECT greatest(90000, coalesce(max(substring(sku FROM '^PB-(\d+)$')::int), 0)) AS n FROM "products" WHERE sku ~ '^PB-\d+$'
),
todo AS (SELECT v.* FROM "_m81" v WHERE NOT EXISTS (SELECT 1 FROM "products" e WHERE e.slug = v.slug OR lower(e.name) = lower(v.name))),
ins AS (
  INSERT INTO "products" ("slug", "sku", "name", "category", "sub", "extra_subs", "icon", "origin", "ship", "unit", "spec", "lead", "specs", "keywords", "attrs", "active", "no_voucher", "created_at")
  SELECT t.slug, 'PB-' || (base.n + row_number() OVER (ORDER BY t.ord)), t.name, 'phan-bon',
    CASE WHEN EXISTS (SELECT 1 FROM "subcategories" s WHERE s.category_slug = 'phan-bon' AND s.slug = 'phan-tan-cham') THEN 'phan-tan-cham' ELSE (SELECT slug FROM "subcategories" WHERE category_slug = 'phan-bon' ORDER BY sort LIMIT 1) END,
    '[]'::jsonb, 'fertilizer', 'Việt Nam', 'supply', t.unit, t.spec, t.lead, t.specs, '["Rynan","phân tan chậm","phân thông minh"]'::jsonb, '{}'::jsonb, true, true, now() + t.ord * interval '1 millisecond'
  FROM todo t, base RETURNING "slug"
)
INSERT INTO "_m81_new" SELECT slug FROM ins;--> statement-breakpoint
INSERT INTO "product_options" ("product_slug", "idx", "label", "price", "old_price", "garden", "cost", "combo2", "bulky", "stock")
SELECT m.slug, (o.ord - 1)::int, o.value->>'label', (o.value->>'price')::int, NULL, (o.value->>'garden')::int, (o.value->>'cost')::int, NULL, false, (o.value->>'qty')::int
FROM "_m81" m JOIN "_m81_new" n ON n.slug = m.slug, jsonb_array_elements(m.options) WITH ORDINALITY AS o(value, ord);--> statement-breakpoint
INSERT INTO "product_images" ("product_slug", "idx", "file", "mime", "data", "option_idx")
SELECT m.slug, (o.ord - 1)::int, o.value->>'img', 'external', ''::bytea, CASE WHEN jsonb_array_length(m.options) > 1 THEN (o.ord - 1)::int END
FROM "_m81" m JOIN "_m81_new" n ON n.slug = m.slug, jsonb_array_elements(m.options) WITH ORDINALITY AS o(value, ord)
WHERE o.value->>'img' IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "product_images" x WHERE x.file = o.value->>'img');--> statement-breakpoint
WITH st AS (SELECT id FROM "stores" WHERE "active" ORDER BY is_default DESC, id LIMIT 1),
lots AS (
  INSERT INTO "stock_lots" ("store_id", "product_slug", "option_idx", "qty", "unit_cost", "expiry")
  SELECT st.id, o.product_slug, o.idx, o.stock, o.garden, '2029-01-01'
  FROM "product_options" o JOIN "_m81_new" n ON n.slug = o.product_slug, st
  WHERE NOT o.deleted AND NOT EXISTS (SELECT 1 FROM "stock_lots" l WHERE l.product_slug = o.product_slug AND l.option_idx = o.idx)
  RETURNING id, store_id, product_slug, option_idx, qty
)
INSERT INTO "stock_moves" ("product_slug", "option_idx", "store_id", "lot_id", "delta", "after", "reason", "note", "actor")
SELECT product_slug, option_idx, store_id, id, qty, qty, 'import', 'Nhập phân Rynan 02/11/2026', 'Hệ thống' FROM lots;--> statement-breakpoint
DROP TABLE "_m81_new";--> statement-breakpoint
DROP TABLE "_m81";
